/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.view.C3;import page2020.view.bs4.B4text.TextX;import page2020.view.html5.H5a;import page2020.view.html5.H5button;import page2020.view.html5.H5img;import page2020.view.html5.H5span;public class B4navbar extends B4boxes<B4navbar> {	public static final String navbar = "navbar";	public static final String expend = "navbar-expand-";	public static final String dark = "navbar-dark";	public static final String light = "navbar-light";	public static final String brand = "navbar-brand";	public static final String text = "navbar-text";	public static final String toggler = "navbar-toggler";	public static final String icon = "navbar-toggler-icon";	public static final String collapse = "navbar-collapse";	public static final String nav = "navbar-nav";	private String id;	public B4navbar() {		super("nav");		super.data(PageKey.type, "navbar");		super.cssClass(navbar);	}	public B4navbar expend(int number) {		String size = B4box.sizeName(number);		if (size != null) {			super.boxes().cssClass(expend + size);		}		return this;	}	public B4navbar brand(H5a a, String height) {		a.cssClass(brand).css(C3.margin("0"), C3.padding("0"));		int count = a.count();		for (int i=0; i < count; i++) {			if (a.get(i) instanceof H5img) {				((H5img) a.get(i)).css(C3.height(height)); 			}		}		return super.boxes().append(a);	}	public B4navbar header(H5span span) {		return super.boxes().append(span.cssClass(text, TextX.nowrap));	}	public B4navbar toggler() {		this.id = B4ctrl.id();		return super.boxes().append(			new H5button()				.cssClass(toggler, light, B4border.border, "mr-2")				.data(B4ctrl.toggle, B4ctrl.collapse)				.data(B4ctrl.target, "#" + this.id)				.append(new H5span().cssClass(icon))		);	}	public B4navbar nav() {		B4nav ul = new B4nav().cssClass(nav).removeClass(B4nav.nav);		if (this.id != null) {			B4element div = new B4element().id(this.id).cssClass(B4ctrl.collapse, collapse);			super.boxes().append(div.append(ul));		} else {			super.boxes().append(ul);		}		super.setBox(ul);		return this;	}	public B4navbar item(H5a a) {		((B4nav) super.box()).item(a);		return this;	}	public B4navbar item(B4dropdown dropdown) {		((B4nav) super.box()).item(dropdown);		return this;	}}